// 1. Input Validation
if (ep_input.position_eci_m == NULL || ep_input.sun_direction_eci == NULL) {
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

if (!adcs_is_finite_vec3(ep_input.position_eci_m) || !adcs_is_finite_vec3(ep_input.sun_direction_eci)) {
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

if (ep_config.earth_radius_m <= 0.0) {
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

if (ep_config.recovery_cycles < 1 || ep_config.recovery_cycles > 100 ||
    ep_config.warmup_cycles < 1 || ep_config.warmup_cycles > 100) {
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

if (!isfinite(ep_input.battery_soc) || ep_input.battery_soc < 0.0 || ep_input.battery_soc > 1.0 ||
    !isfinite(ep_config.payload_on_soc) || ep_config.payload_on_soc < 0.0 || ep_config.payload_on_soc > 1.0 ||
    !isfinite(ep_config.payload_off_soc) || ep_config.payload_off_soc < 0.0 || ep_config.payload_off_soc > 1.0 ||
    ep_config.payload_off_soc > ep_config.payload_on_soc) {
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

if (ep_input.enable != 0 && ep_input.enable != 1) {
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

// 2. Disabled State
if (ep_input.enable == 0) {
    ep_output.mode = EP_SUN;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    ep_state.mode = EP_SUN; // Reset state as per "Disable resets SUN"
    return;
}

// 3. Geometry Calculation
adcs_vec3_t sun_dir_norm;
adcs_status_t norm_status = adcs_vec3_normalize(ep_input.sun_direction_eci, ADCS_EPS_NORM, &sun_dir_norm);
if (norm_status != ADCS_OK) {
     ep_output.mode = EP_FAULT;
     ep_output.elapsed = 0;
     ep_output.payload_on = 0;
     ep_output.heater_on = 0;
     ep_output.axial_m = 0.0;
     ep_output.cross_track_m = 0.0;
     return;
}

double axial_m = adcs_vec3_dot(ep_input.position_eci_m, &sun_dir_norm);
adcs_vec3_t proj_vec = adcs_vec3_scale(&sun_dir_norm, axial_m);
adcs_vec3_t perp_vec = adcs_vec3_sub(ep_input.position_eci_m, &proj_vec);
double cross_track_m = adcs_vec3_norm(&perp_vec);

ep_output.axial_m = axial_m;
ep_output.cross_track_m = cross_track_m;

int is_eclipse = (axial_m < 0.0) && (cross_track_m < ep_config.earth_radius_m);

// 4. Eclipse Handling
if (is_eclipse) {
    ep_output.mode = EP_ECLIPSE;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 1;
    ep_state.mode = EP_ECLIPSE;
    return;
}

// 5. Sunlight Handling
static unint32 recovery_count = 0;
static unint32 warmup_count = 0;

ep_mode_t prev_mode = ep_state.mode;
ep_mode_t next_mode = prev_mode;

if (prev_mode == EP_ECLIPSE) {
    recovery_count = 1;
    warmup_count = 0;
    next_mode = EP_RECOVERY;
} else if (prev_mode == EP_RECOVERY) {
    recovery_count++;
    if (recovery_count >= ep_config.recovery_cycles) {
        next_mode = EP_WARMUP;
        warmup_count = 1;
        recovery_count = 0;
    } else {
        next_mode = EP_RECOVERY;
    }
} else if (prev_mode == EP_WARMUP) {
    warmup_count++;
    if (warmup_count >= ep_config.warmup_cycles) {
        if (ep_input.battery_soc >= ep_config.payload_on_soc) {
            next_mode = EP_SUN;
        } else {
            next_mode = EP_LOADWAIT;
        }
        warmup_count = 0;
        recovery_count = 0;
    } else {
        next_mode = EP_WARMUP;
    }
} else if (prev_mode == EP_LOADWAIT) {
    if (ep_input.battery_soc >= ep_config.payload_on_soc) {
        next_mode = EP_SUN;
    } else {
        next_mode = EP_LOADWAIT;
    }
    warmup_count = 0;
    recovery_count = 0;
} else if (prev_mode == EP_SUN) {
    if (ep_input.battery_soc < ep_config.payload_off_soc) {
        next_mode = EP_LOADSHED;
    } else {
        next_mode = EP_SUN;
    }
    warmup_count = 0;
    recovery_count = 0;
} else if (prev_mode == EP_LOADSHED) {
    if (ep_input.battery_soc >= ep_config.payload_on_soc) {
        next_mode = EP_SUN;
    } else {
        next_mode = EP_LOADSHED;
    }
    warmup_count = 0;
    recovery_count = 0;
} else {
    // Initial or Fault recovery
    recovery_count = 1;
    next_mode = EP_RECOVERY;
}

ep_state.mode = next_mode;

ep_output.mode = next_mode;
ep_output.payload_on = 0;
ep_output.heater_on = 0;

switch (next_mode) {
    case EP_RECOVERY:
        ep_output.elapsed = recovery_count;
        break;
    case EP_WARMUP:
        ep_output.elapsed = warmup_count;
        break;
    case EP_SUN:
        ep_output.elapsed = 0;
        ep_output.payload_on = 1;
        break;
    case EP_LOADWAIT:
        ep_output.elapsed = 0;
        break;
    case EP_LOADSHED:
        ep_output.elapsed = 0;
        break;
    case EP_ECLIPSE:
        ep_output.elapsed = 0;
        break;
    case EP_FAULT:
        ep_output.elapsed = 0;
        break;
}

